return {
  mode: "context",
  taskTitle: "Desplegar la App de Gestión de Usuarios (v0.1)",
  currentDescription: "Usar servicio de deployment para la app",
  contextTasks: [
    {
      title: "Configuración Inicial: Base de Datos de Usuarios",
      description:
        "Establecer la conexión con **MongoDB Atlas** y definir el **esquema** para la colección de 'usuarios' (campos: nombre, email, password_hash, rol).",
      column: "Done",
    },
    {
      title: "Implementar Sistema de Autenticación (Login/Registro)",
      description:
        "Crear los **endpoints API** para registro (POST /api/auth/register) y login (POST /api/auth/login), incluyendo **validación de datos** y uso de **JWT** para sesiones.",
      column: "In Progress",
    },
    {
      title: "Pruebas Unitarias de Backend",
      description:
        "Escribir pruebas que cubran los casos de uso básicos de la **API de Usuarios** (CRUD: Crear, Leer, Actualizar, Eliminar) y los flujos de **autenticación**.",
      column: "To Do",
    },
  ],
};

// Input: $input.all() o $json.contextTasks
const contextTasks = $json.contextTasks || [];

const tasksByColumn = contextTasks.reduce((acc, task) => {
  if (!acc[task.column]) {
    acc[task.column] = [];
  }
  acc[task.column].push(task);
  return acc;
}, {});

let summary = '';
Object.entries(tasksByColumn).forEach(([column, columnTasks]) => {
  summary += `\n${column} (${columnTasks.length} tareas):\n`;
  columnTasks.slice(0, 5).forEach((task) => {
    summary += `  - ${task.title}\n`;
  });
  if (columnTasks.length > 5) {
    summary += `  ... y ${columnTasks.length - 5} más\n`;
  }
});

// Output: Agrega el summary al JSON
return {
  ...$json,
  contextSummary: summary
};
